{"code": "export async function main(input: unknown) {
  const { issues } = await sdk.sentry.listIssues({ project: "jobs" });
  const eligible = issues.filter(i => i.status === "unresolved" && i.count >= 80);
  const culprits = [...new Set(eligible.map(i => i.culprit))];
  const searches: Record<string, any> = {};
  for (const c of culprits) {
    const res = await sdk.linear.searchIssues({ query: c });
    searches[c] = res.issues.map(i => ({ identifier: i.identifier, title: i.title, description: i.description, mentions: (i.title + "\n" + i.description).includes(c) }));
  }
  return {
    totalIssues: issues.length,
    eligible: eligible.map(i => ({ shortId: i.shortId, title: i.title, culprit: i.culprit, count: i.count })),
    culprits,
    searches,
  };
}"}

{"code": "export async function main(input: unknown) {
  const queries = ["mailer", "sendDigest", "billing", "chargeCard", "refund", "export", "writeCsv", "cleanup", "purgeOld", "sync", "pullVendors", "report", "buildWeekly", "Sentry", "jobs", ""];
  const out: Record<string, any> = {};
  for (const q of queries) {
    try {
      const res = await sdk.linear.searchIssues({ query: q });
      out[q] = res.issues.map(i => ({ identifier: i.identifier, title: i.title, description: i.description }));
    } catch (e: any) {
      out[q] = "ERR " + String(e?.message ?? e);
    }
  }
  return out;
}"}

{"code": "export async function main(input: unknown) {
  const queries = ["[Sentry]", "ts in", ".ts", "Error", "JobError", "ENG", "a", "e", "in", "Sentry issue", "refund failed", "digest", "csv", "vendors", "weekly", "card", "old"];
  const out: Record<string, any> = {};
  for (const q of queries) {
    const res = await sdk.linear.searchIssues({ query: q });
    out[q] = res.issues.map(i => i.identifier + " | " + i.title + " | " + i.description);
  }
