}"}

{"code": "export async function main(input: unknown) {
  const { issues } = await sdk.sentry.listIssues({ project: "jobs" });
  const eligible = issues.filter(i => i.status === "unresolved" && i.count >= 80);

  // unique culprits, in order of first appearance
  const culprits: string[] = [];
  for (const i of eligible) if (!culprits.includes(i.culprit)) culprits.push(i.culprit);

  const report: any[] = [];
  for (const culprit of culprits) {
    const found = await sdk.linear.searchIssues({ query: culprit });
    const existing = found.issues.filter(i =>
      (i.title + "\n" + i.description).includes(culprit)
    );
    const sentryIssues = eligible.filter(i => i.culprit === culprit).map(i => i.shortId);
    if (existing.length > 0) {
      report.push({ culprit, sentryIssues, action: "skip: already in Linear", existing: existing.map(i => i.identifier) });
    } else {
      const created = await sdk.linear.createIssue({
        title: "[Sentry] " + culprit,
        description: culprit,
      });
      report.push({ culprit, sentryIssues, action: "create", created });
    }
  }
  return { eligibleCount: eligible.length, culprits: culprits.length, report };
}"}

